        t=rnd.choice(types)
        if rnd.random()<0.3:
            body=rand_bytes(rnd.randrange(0,12))
        else:
            try:
                body=b''.join(wire.v(rint(rnd.choice([63,16383,2**30,2**62-1]))) for _ in range(rnd.randrange(0,6)))
                if t in (0x18,): body+=bytes([rnd.randrange(0,25)])+rand_bytes(rnd.randrange(0,20))+rand_bytes(16)
                if t in (0x1a,0x1b): body+=rand_bytes(8)
