            out+=(wire.v(t) if rnd.random()<0.8 else bytes([t]))+body
        except Exception: pass
    return out
def trace():
    ncid=rnd.randrange(1,5)
    width=rnd.randrange(1,21)
    cids=[rand_bytes(width) for _ in range(ncid)]
    # dedupe
    seen=set(); lc=[]
